C.resolvectl=C["systemd-resolve"]=(x,a)=>{const w=W(x);if(a[0]==="query"&&a[1]){const ip=LX.resolve(w,a[1]);if(!ip){e(x,`${a[1]}: resolve call failed: '${a[1]}' not found\n`);return 1}o(x,`${a[1]}: ${ip}                     -- link: eth0\n\n-- Information acquired via protocol DNS in 12.4ms.\n-- Data is authenticated: no; Data was acquired via local or encrypted transport: no\n`);return 0}
  if(a[0]==="flush-caches")return 0;o(x,`Global\n           Protocols: -LLMNR -mDNS -DNSOverTLS DNSSEC=no/unsupported\n    resolv.conf mode: stub\n\nLink 2 (eth0)\n    Current Scopes: DNS\n         Protocols: +DefaultRoute -LLMNR -mDNS -DNSOverTLS DNSSEC=no/unsupported\nCurrent DNS Server: ${LX.nameservers(w)[0]||""}\n       DNS Servers: ${LX.nameservers(w).join(" ")}\n        DNS Domain: example.lan\n`);return 0};
